   578→    println!("  cargo xtask {cmd} ex-musl -opt  # {cmd} ex-musl with nightly optimizations");
   579→}
   580→
   581→fn print_test_help() {
   582→    println!("Usage: cargo xtask test [OPTIONS] [CRATES]...");
