    36→/// Find the workspace root by looking for Cargo.toml with [workspace]
    37→pub fn find_workspace_root() -> Result<PathBuf> {
    38→    let mut dir = std::env::current_dir()?;
    39→    loop {
    40→        let cargo_toml = dir.join("Cargo.toml");
    41→        if cargo_toml.exists() {
    42→            let content = std::fs::read_to_string(&cargo_toml)?;
    43→            if content.contains("[workspace]") {
    44→                return Ok(dir);
    45→            }
    46→        }
    47→        if !dir.pop() {
    48→            bail!("could not find workspace root");
    49→        }
    50→    }
    51→}
    52→
    53→/// Find a crate's directory - tries as path first, then searches libs/ and apps/
    54→pub fn find_crate_dir(workspace: &Path, name: &str) -> Result<PathBuf> {
    55→    // Try as path first (relative or absolute)
    56→    let as_path = PathBuf::from(name);
    57→    if as_path.join("Cargo.toml").exists() {
    58→        return Ok(as_path.canonicalize().unwrap_or(as_path));
    59→    }
    60→
    61→    // Fallback: search libs/ and apps/
    62→    for prefix in ["libs", "apps"] {
    63→        let path = workspace.join(prefix).join(name);
    64→        if path.join("Cargo.toml").exists() {
    65→            return Ok(path);
    66→        }
    67→    }
    68→    bail!("crate '{}' not found", name);
    69→}
    70→
    71→/// Find the tspec for a crate - tries as path first, then relative to crate_dir
    72→/// Returns None if no tspec exists (plain cargo build will be used)
    73→pub fn find_tspec(crate_dir: &Path, explicit: Option<&str>) -> Result<Option<PathBuf>> {
    74→    match explicit {
    75→        Some(name) => {
    76→            // Try as path first (relative to cwd or absolute)
    77→            let as_path = PathBuf::from(name);
    78→            if as_path.exists() {
    79→                return Ok(Some(as_path.canonicalize().unwrap_or(as_path)));
    80→            }
    81→
    82→            // Fallback: relative to crate directory
    83→            let in_crate = crate_dir.join(name);
    84→            if in_crate.exists() {
    85→                return Ok(Some(in_crate));
    86→            }
    87→
    88→            bail!("tspec not found: {}", name);
    89→        }
    90→        None => {
    91→            let default = crate_dir.join("tspec.toml");
    92→            if default.exists() {
    93→                Ok(Some(default))
    94→            } else {
    95→                Ok(None) // No tspec = plain cargo build
    96→            }
    97→        }
    98→    }
    99→}
