/// Find the spec for a crate - tries as path first, then relative to crate_dir
/// Returns None if no spec exists (plain cargo build will be used)
pub fn find_spec(crate_dir: &Path, explicit: Option<&str>) -> Result<Option<PathBuf>> {
    match explicit {
        Some(name) => {
            // Try as path first (relative to cwd or absolute)
            let as_path = PathBuf::from(name);
            if as_path.exists() {
                return Ok(Some(as_path.canonicalize().unwrap_or(as_path)));
            }

            // Fallback: relative to crate directory
            let in_crate = crate_dir.join(name);
            if in_crate.exists() {
                return Ok(Some(in_crate));
            }

            // Try with .xt.toml suffix if name has no extension
            if !name.contains('.') {
                let with_suffix = crate_dir.join(format!("{}.xt.toml", name));
                if with_suffix.exists() {
                    return Ok(Some(with_suffix));
                }
            }

            bail!("spec not found: {}", name);
        }
        None => {
            let default = crate_dir.join("spec.xt.toml");
            if default.exists() {
                Ok(Some(default))
            } else {
                Ok(None) // No spec = plain cargo build
            }
        }
    }
}

/// Backwards compatibility alias
pub fn find_tspec(crate_dir: &Path, explicit: Option<&str>) -> Result<Option<PathBuf>> {
    find_spec(crate_dir, explicit)
}

