use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(name = "xt")]
#[command(about = "Translation spec based build system")]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand)]
pub enum Commands {
    /// Build a crate with a translation spec
    Build {
        /// Crate to build
        crate_name: String,
        /// Translation spec to use (defaults to crate's tspec.xt.toml)
        #[arg(short = 't', long = "tspec")]
        tspec: Option<String>,
        /// Release build
        #[arg(short, long)]
        release: bool,
        /// Strip symbols from binary after build
        #[arg(short, long)]
        strip: bool,
    },
    /// Build and run a crate with a translation spec
    Run {
        /// Crate to run
        crate_name: String,
        /// Translation spec to use (defaults to crate's tspec.xt.toml)
        #[arg(short = 't', long = "tspec")]
        tspec: Option<String>,
        /// Release build
        #[arg(short, long)]
        release: bool,
        /// Strip symbols from binary before running
        #[arg(short, long)]
        strip: bool,
    },
    /// Test a crate with a translation spec
    Test {
        /// Crate to test
        crate_name: String,
        /// Translation spec to use (defaults to crate's tspec.xt.toml)
        #[arg(short = 't', long = "tspec")]
        tspec: Option<String>,
        /// Release build
        #[arg(short, long)]
        release: bool,
    },
    /// Compare two specs for a crate (size and behavior)
    Compare {
        /// Crate to compare
        crate_name: String,
        /// First spec file
