//! Batch operations on all workspace crates
//!
//! Provides build_all, run_all, test_all for operating on all workspace members.

use std::process::ExitCode;

use crate::binary::strip_binary;
use crate::build::build_crate;
use crate::run::run_binary;
use crate::testing::test_crate;
use crate::workspace::{CrateKind, WorkspaceInfo};

/// Result of a batch operation on a single crate
pub struct OpResult {
    pub name: String,
    pub success: bool,
    pub message: String,
}

/// Build all workspace crates (excluding build tools)
pub fn build_all(
    workspace: &WorkspaceInfo,
    tspec: Option<&str>,
    release: bool,
    strip: bool,
    fail_fast: bool,
) -> Vec<OpResult> {
    let mut results = Vec::new();

    for member in workspace.buildable_members() {
        println!("=== {} ===", member.name);

        let result = match build_crate(&member.name, tspec, release) {
            Ok(build_result) => {
                if strip && member.has_binary {
                    if let Err(e) = strip_binary(&build_result.binary_path) {
                        eprintln!("  warning: strip failed: {}", e);
                    }
                }
                OpResult {
                    name: member.name.clone(),
                    success: true,
                    message: format!("{}", build_result.binary_path.display()),
                }
            }
            Err(e) => OpResult {
                name: member.name.clone(),
                success: false,
                message: e.to_string(),
            },
        };

        let failed = !result.success;
        results.push(result);

        if failed && fail_fast {
            break;
        }
    }

    results
}

/// Run all app crates sequentially
pub fn run_all(
    workspace: &WorkspaceInfo,
    tspec: Option<&str>,
    release: bool,
    strip: bool,
) -> Vec<OpResult> {
    let mut results = Vec::new();

    for member in workspace.runnable_members() {
        println!("=== {} ===", member.name);

        let result = match build_crate(&member.name, tspec, release) {
            Ok(build_result) => {
                if strip {
                    if let Err(e) = strip_binary(&build_result.binary_path) {
                        eprintln!("  warning: strip failed: {}", e);
                    }
                }
                match run_binary(&build_result.binary_path) {
                    Ok(exit_code) => OpResult {
                        name: member.name.clone(),
                        success: true, // We don't treat non-zero exit as failure
                        message: format!("exit code: {}", exit_code),
                    },
                    Err(e) => OpResult {
                        name: member.name.clone(),
                        success: false,
                        message: format!("run failed: {}", e),
                    },
                }
            }
            Err(e) => OpResult {
                name: member.name.clone(),
                success: false,
                message: format!("build failed: {}", e),
            },
        };

        results.push(result);
    }

    results
}

/// Test all workspace crates
pub fn test_all(
    workspace: &WorkspaceInfo,
    tspec: Option<&str>,
    release: bool,
    fail_fast: bool,
) -> Vec<OpResult> {
    let mut results = Vec::new();

    // Test regular crates (excluding Test kind which needs special handling)
    for member in workspace.buildable_members() {
        if member.kind == CrateKind::Test {
            continue; // Handle test crates separately
        }

        println!("=== {} ===", member.name);

        let result = match test_crate(&member.name, tspec, release) {
            Ok(()) => OpResult {
                name: member.name.clone(),
                success: true,
                message: "ok".to_string(),
            },
            Err(e) => OpResult {
                name: member.name.clone(),
                success: false,
                message: e.to_string(),
            },
        };

        let failed = !result.success;
        results.push(result);

        if failed && fail_fast {
            return results;
        }
    }

    // Handle test crates (like rlibc-x2-tests) - build and run the binaries
    for member in workspace.test_members() {
        println!("=== {} ===", member.name);

        // Build the test crate
        let build_result = match build_crate(&member.name, tspec, release) {
            Ok(r) => r,
            Err(e) => {
                results.push(OpResult {
                    name: member.name.clone(),
                    success: false,
                    message: format!("build failed: {}", e),
                });
                if fail_fast {
                    return results;
                }
                continue;
            }
        };

        // Run the test binary
        let result = match run_binary(&build_result.binary_path) {
            Ok(exit_code) => {
                if exit_code == 0 {
                    OpResult {
                        name: member.name.clone(),
                        success: true,
                        message: "ok".to_string(),
                    }
                } else {
                    OpResult {
                        name: member.name.clone(),
                        success: false,
                        message: format!("exit code: {}", exit_code),
                    }
                }
            }
            Err(e) => OpResult {
                name: member.name.clone(),
                success: false,
                message: format!("run failed: {}", e),
            },
        };

        let failed = !result.success;
        results.push(result);

        if failed && fail_fast {
            return results;
        }
    }

    results
}

/// Print a summary of operation results
pub fn print_summary(results: &[OpResult]) -> ExitCode {
    println!();
    println!("========================================");
    println!("               SUMMARY");
    println!("========================================");
    println!();

    let mut passed = 0;
    let mut failed = 0;

    for result in results {
        let status = if result.success {
            passed += 1;
            "PASS"
        } else {
            failed += 1;
            "FAIL"
        };
        println!("  [{status}] {}", result.name);
    }

    println!();
    println!("  Total: {} passed, {} failed", passed, failed);
    println!("========================================");
    println!();

    if failed > 0 {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

