            continue; // Handle test crates separately
        }

        println!("=== {} ===", member.name);

        let result = match test_crate(&member.name, tspec, release) {
            Ok(()) => OpResult {
                name: member.name.clone(),
                success: true,
                message: "ok".to_string(),
            },
            Err(e) => OpResult {
                name: member.name.clone(),
                success: false,
                message: e.to_string(),
            },
        };

        let failed = !result.success;
        results.push(result);

        if failed && fail_fast {
            return results;
        }
    }

    // Handle test crates (like rlibc-x2-tests) - build and run all test binaries
    for member in workspace.test_members() {
        println!("=== {} ===", member.name);

        // Build the test crate (builds all binaries)
        if let Err(e) = build_crate(&member.name, tspec, release) {
            results.push(OpResult {
                name: member.name.clone(),
                success: false,
                message: format!("build failed: {}", e),
            });
            if fail_fast {
                return results;
            }
            continue;
        }

        // Find and run all test binaries in the target directory
        let profile = if release { "release" } else { "debug" };
        let target_dir = workspace.root.join("target").join(profile);

        // Look for binaries that end with "-tests" in the target directory
        let test_binaries: Vec<_> = std::fs::read_dir(&target_dir)
            .into_iter()
            .flatten()
            .filter_map(|e| e.ok())
            .filter(|e| {
                let name = e.file_name().to_string_lossy().to_string();
                let is_file = e.path().is_file();
                let is_test = name.ends_with("-tests");
                let is_executable = e.metadata().map(|m| m.permissions().mode() & 0o111 != 0).unwrap_or(false);
                is_file && is_test && is_executable
            })
            .collect();

        if test_binaries.is_empty() {
            results.push(OpResult {
                name: member.name.clone(),
                success: false,
                message: "no test binaries found".to_string(),
            });
            continue;
        }

        for entry in test_binaries {
            let path = entry.path();
            let bin_name = entry.file_name().to_string_lossy().to_string();

            print!("  Running {}... ", bin_name);

            let result = match run_binary(&path) {
                Ok(exit_code) => {
                    if exit_code == 0 {
                        println!("ok");
                        OpResult {
                            name: format!("{}/{}", member.name, bin_name),
                            success: true,
                            message: "ok".to_string(),
                        }
                    } else {
                        println!("FAILED (exit {})", exit_code);
                        OpResult {
                            name: format!("{}/{}", member.name, bin_name),
                            success: false,
                            message: format!("exit code: {}", exit_code),
                        }
                    }
                }
                Err(e) => {
                    println!("FAILED");
                    OpResult {
                        name: format!("{}/{}", member.name, bin_name),
                        success: false,
                        message: format!("run failed: {}", e),
                    }
                }
            };

            let failed = !result.success;
            results.push(result);

            if failed && fail_fast {
                return results;
            }
        }
    }

    results
}

/// Print a summary of operation results
pub fn print_summary(results: &[OpResult]) -> ExitCode {
    println!();
    println!("========================================");
    println!("               SUMMARY");
    println!("========================================");
    println!();

    let mut passed = 0;
    let mut failed = 0;

    for result in results {
        let status = if result.success {
            passed += 1;
            "PASS"
        } else {
            failed += 1;
            "FAIL"
        };
        println!("  [{status}] {}", result.name);
    }

    println!();
    println!("  Total: {} passed, {} failed", passed, failed);
    println!("========================================");
    println!();

    if failed > 0 {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

# Plan: Add "All Crates" Mode + Rename to *.xt.toml Pattern

## Overview

Two related changes to complete xt feature parity with xtask:

1. **Rename spec files**: `tspec.toml` → `tspec.xt.toml` (extension pattern `*.xt.toml`) ✅ DONE
2. **Add "all crates" mode**: Auto-discover workspace members when no crate specified

## Naming Convention

All spec files use `.xt.toml` as the extension:
```
tspec.xt.toml                # Default (when -t not specified)
optimized.xt.toml            # Named variant
minimal.xt.toml              # Another variant
optimized-001-abc123.xt.toml # Snapshot of "optimized"
```

Glob pattern `*.xt.toml` matches all spec files.

### Flexible `-t` Resolution

When `-t name` is specified, resolve in order:
1. Try exact path (absolute or relative to cwd)
2. Try exact path relative to crate directory
3. Try with `.xt.toml` suffix appended (in crate directory)
4. Error if none found

Examples:
```bash
cargo xt build foo -t optimized        # finds optimized.xt.toml
cargo xt build foo -t optimized.xt.toml  # exact match
cargo xt build foo -t legacy.toml      # works (no forced suffix)
cargo xt build foo -t ../shared/base.xt.toml  # relative path
```

The `.xt.toml` convention is suggested, not enforced.

## Part A: Rename tspec.toml to tspec.xt.toml ✅ COMPLETED

Changes made:
- Default filename: `tspec.toml` → `tspec.xt.toml`
- Keep `-t`/`--tspec` flag (meaningful: "Translation Spec")
- Help text updated to reference `tspec.xt.toml`
- Snapshot naming: `{name}-{seq:03}-{hash}.xt.toml`
- Suffix fallback: `-t optimized` finds `optimized.xt.toml`
- Files renamed: `apps/ex-{x1,x2,musl}-xt/tspec.xt.toml`

Documentation updates deferred to Part C.

---

## Part B: Add "All Crates" Mode

### B1. Add cargo_metadata Dependency

In `xt/Cargo.toml`:
```toml
[dependencies]
cargo_metadata = "0.18"
```

### B2. Create workspace.rs Module (~80 lines)

New file: `xt/src/workspace.rs`

```rust
use anyhow::Result;
use cargo_metadata::MetadataCommand;
use std::path::PathBuf;

/// Crate classification for behavior differences
#[derive(Debug, Clone, PartialEq)]
pub enum CrateKind {
    App,      // apps/* - has binary, runnable
    Lib,      // libs/* - library only
    Tool,     // tools/* - utility binaries
    Test,     // */tests - test binaries (special handling)
    BuildTool, // xt, xtask - excluded by default
}

pub struct CrateMember {
    pub name: String,
    pub path: PathBuf,
    pub has_binary: bool,
    pub kind: CrateKind,
}

pub struct WorkspaceInfo {
    pub root: PathBuf,
    pub members: Vec<CrateMember>,
}

impl WorkspaceInfo {
    pub fn discover() -> Result<Self> { ... }

    /// Get members excluding build tools (xt, xtask)
    pub fn buildable_members(&self) -> Vec<&CrateMember> {
        self.members.iter()
            .filter(|m| m.kind != CrateKind::BuildTool)
            .collect()
    }

    /// Get members that can be run (have binaries, not libs)
    pub fn runnable_members(&self) -> Vec<&CrateMember> {
        self.members.iter()
            .filter(|m| m.has_binary && m.kind != CrateKind::BuildTool)
            .collect()
    }
}

fn classify_crate(path: &Path) -> CrateKind {
    let path_str = path.to_string_lossy();
    if path_str.contains("/tests") || path_str.ends_with("-tests") {
        CrateKind::Test
    } else if path_str.contains("apps/") {
        CrateKind::App
    } else if path_str.contains("libs/") {
        CrateKind::Lib
    } else if path_str.contains("tools/") {
        CrateKind::Tool
    } else {
        // xt, xtask at root level
        CrateKind::BuildTool
    }
}
```

### B3. CLI Changes

In `xt/src/cli.rs`, make `crate_name` optional for Build, Run, Test:

```rust
Build {
    /// Crate to build (omit for all workspace members)
    crate_name: Option<String>,
    #[arg(short = 't', long = "spec")]
    spec: Option<String>,
    #[arg(short, long)]
    release: bool,
    #[arg(short, long)]
    strip: bool,
    #[arg(short, long)]
    quiet: bool,
    #[arg(short, long)]
    fail_fast: bool,
}
```

Similar changes for Run and Test commands.

### B4. Main Loop Logic

In `xt/src/main.rs`, add dispatch for "all" mode:

```rust
Commands::Build { crate_name: None, spec, release, strip, quiet, fail_fast } => {
    let workspace = WorkspaceInfo::discover()?;
    let results = build_all(&workspace, spec.as_deref(), release, strip, quiet, fail_fast)?;
    // Handle results
}
Commands::Build { crate_name: Some(name), ... } => {
    // Existing single-crate logic
}
```

### B5. Add all.rs Module (~100 lines)

New file: `xt/src/all.rs`

```rust
use crate::workspace::{WorkspaceInfo, CrateKind};

pub struct BuildResult {
    pub name: String,
    pub success: bool,
    pub message: String,
}

pub fn build_all(
    workspace: &WorkspaceInfo,
    spec: Option<&str>,
    release: bool,
    strip: bool,
    quiet: bool,
    fail_fast: bool,
) -> Result<Vec<BuildResult>> {
    let mut results = Vec::new();

    for member in workspace.buildable_members() {
        println!("=== {} ===", member.name);
        match build_crate(&member.name, spec, release) {
            Ok(result) => {
                if strip { strip_binary(&result.binary_path)?; }
                results.push(BuildResult { name: member.name.clone(), success: true, ... });
            }
            Err(e) => {
                results.push(BuildResult { name: member.name.clone(), success: false, ... });
                if fail_fast { break; }
            }
        }
    }

    results
}

pub fn test_all(...) -> Result<Vec<TestResult>> {
    // Similar, with special handling for CrateKind::Test (rlibc-x2-tests)
}

pub fn print_summary(results: &[impl HasStatus]) {
    println!("========================================");
    println!("               SUMMARY");
    // ... pass/fail counts
}
```

### B6. Run Command Behavior

For `cargo xt run` with no crate: **Run all apps sequentially**
- Only run members with `CrateKind::App` (from apps/ directory)
- Show exit code for each
- Continue on non-zero exit (don't treat as failure unless crash)
- Skip libs and tools (no sensible "run" behavior)

### B7. Update lib.rs Exports

```rust
