use crate::binary::strip_binary;
use crate::build::build_crate;
use crate::run::run_binary;
use crate::testing::test_crate;
use crate::workspace::{CrateKind, WorkspaceInfo};

/// Result of a batch operation on a single crate
pub struct OpResult {
    pub name: String,
    pub success: bool,
    pub message: String,
}

/// Build all workspace crates (excluding build tools)
pub fn build_all(
    workspace: &WorkspaceInfo,
    tspec: Option<&str>,
    release: bool,
    strip: bool,
    fail_fast: bool,
) -> Vec<OpResult> {
    let mut results = Vec::new();

    for member in workspace.buildable_members() {
        println!("=== {} ===", member.name);

        let result = match build_crate(&member.name, tspec, release) {
            Ok(build_result) => {
                if strip && member.has_binary {
                    if let Err(e) = strip_binary(&build_result.binary_path) {
                        eprintln!("  warning: strip failed: {}", e);
                    }
                }
                OpResult {
                    name: member.name.clone(),
                    success: true,
                    message: format!("{}", build_result.binary_path.display()),
                }
            }
            Err(e) => OpResult {
                name: member.name.clone(),
                success: false,
                message: e.to_string(),
            },
        };

        let failed = !result.success;
        results.push(result);

        if failed && fail_fast {
            break;
        }
    }

    results
}

/// Run all app crates sequentially
pub fn run_all(
    workspace: &WorkspaceInfo,
    tspec: Option<&str>,
    release: bool,
    strip: bool,
) -> Vec<OpResult> {
    let mut results = Vec::new();

    for member in workspace.runnable_members() {
        println!("=== {} ===", member.name);

        let result = match build_crate(&member.name, tspec, release) {
            Ok(build_result) => {
                if strip {
                    if let Err(e) = strip_binary(&build_result.binary_path) {
                        eprintln!("  warning: strip failed: {}", e);
                    }
                }
                match run_binary(&build_result.binary_path) {
                    Ok(exit_code) => OpResult {
                        name: member.name.clone(),
                        success: true, // We don't treat non-zero exit as failure
                        message: format!("exit code: {}", exit_code),
                    },
                    Err(e) => OpResult {
                        name: member.name.clone(),
                        success: false,
                        message: format!("run failed: {}", e),
                    },
                }
            }
            Err(e) => OpResult {
                name: member.name.clone(),
                success: false,
                message: format!("build failed: {}", e),
            },
        };

        results.push(result);
    }

    results
}

/// Test all workspace crates
pub fn test_all(
    workspace: &WorkspaceInfo,
    tspec: Option<&str>,
    release: bool,
    fail_fast: bool,
) -> Vec<OpResult> {
    let mut results = Vec::new();

    // Test regular crates (excluding Test kind which needs special handling)
    for member in workspace.buildable_members() {
        if member.kind == CrateKind::Test {
            continue; // Handle test crates separately
        }

        println!("=== {} ===", member.name);

        let result = match test_crate(&member.name, tspec, release) {
            Ok(()) => OpResult {
                name: member.name.clone(),
                success: true,
                message: "ok".to_string(),
            },
            Err(e) => OpResult {
                name: member.name.clone(),
                success: false,
                message: e.to_string(),
            },
        };

        let failed = !result.success;
        results.push(result);

        if failed && fail_fast {
            return results;
        }
    }

    // Handle test crates (like rlibc-x2-tests) - build and run all test binaries
    for member in workspace.test_members() {
        println!("=== {} ===", member.name);

        // Build the test crate (builds all binaries)
        if let Err(e) = build_crate(&member.name, tspec, release) {
            results.push(OpResult {
                name: member.name.clone(),
                success: false,
                message: format!("build failed: {}", e),
            });
            if fail_fast {
                return results;
            }
            continue;
        }

        // Find and run all test binaries in the target directory
        let profile = if release { "release" } else { "debug" };
        let target_dir = workspace.root.join("target").join(profile);

        // Look for binaries that end with "-tests" in the target directory
        let test_binaries: Vec<_> = std::fs::read_dir(&target_dir)
            .into_iter()
            .flatten()
            .filter_map(|e| e.ok())
            .filter(|e| {
                let name = e.file_name().to_string_lossy().to_string();
                let is_file = e.path().is_file();
                let is_test = name.ends_with("-tests");
                let is_executable = e.metadata().map(|m| m.permissions().mode() & 0o111 != 0).unwrap_or(false);
                is_file && is_test && is_executable
            })
            .collect();

        if test_binaries.is_empty() {
            results.push(OpResult {
                name: member.name.clone(),
                success: false,
                message: "no test binaries found".to_string(),
            });
            continue;
        }

        for entry in test_binaries {
            let path = entry.path();
            let bin_name = entry.file_name().to_string_lossy().to_string();

            print!("  Running {}... ", bin_name);

            let result = match run_binary(&path) {
                Ok(exit_code) => {
                    if exit_code == 0 {
                        println!("ok");
                        OpResult {
                            name: format!("{}/{}", member.name, bin_name),
                            success: true,
                            message: "ok".to_string(),
                        }
                    } else {
                        println!("FAILED (exit {})", exit_code);
                        OpResult {
                            name: format!("{}/{}", member.name, bin_name),
                            success: false,
                            message: format!("exit code: {}", exit_code),
                        }
                    }
                }
                Err(e) => {
                    println!("FAILED");
                    OpResult {
                        name: format!("{}/{}", member.name, bin_name),
                        success: false,
                        message: format!("run failed: {}", e),
                    }
                }
            };

            let failed = !result.success;
            results.push(result);

            if failed && fail_fast {
                return results;
            }
        }
    }

    results
}

/// Print a summary of operation results (for tests)
pub fn print_test_summary(results: &[OpResult]) -> ExitCode {
    println!();
    println!("========================================");
    println!("               SUMMARY");
    println!("========================================");
    println!();

    let mut passed = 0;
    let mut failed = 0;

    for result in results {
        let status = if result.success {
            passed += 1;
            "PASS"
        } else {
            failed += 1;
            "FAIL"
        };
        println!("  [{status}] {}", result.name);
    }

    println!();
    println!("  Total: {} passed, {} failed", passed, failed);
    println!("========================================");
    println!();

    if failed > 0 {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

/// Print a summary for build/run operations (no PASS/FAIL, just OK/FAILED)
pub fn print_summary(results: &[OpResult]) -> ExitCode {
    println!();
    println!("========================================");
    println!("               SUMMARY");
    println!("========================================");
    println!();

    let mut ok_count = 0;
    let mut failed_count = 0;

    for result in results {
        let status = if result.success {
            ok_count += 1;
            " OK "
        } else {
            failed_count += 1;
            "FAIL"
        };
        println!("  [{status}] {}", result.name);
    }

    println!();
    println!("  Total: {} ok, {} failed", ok_count, failed_count);
    println!("========================================");
    println!();

    if failed_count > 0 {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

use anyhow::Result;
use clap::Parser;
use std::process::ExitCode;

use xt::all::{build_all, print_summary, print_test_summary, run_all, test_all};
use xt::binary::strip_binary;
use xt::build::build_crate;
use xt::cli::{Cli, Commands, SpecCommands};
use xt::compare::compare_specs;
use xt::run::run_binary;
use xt::testing::test_crate;
use xt::workspace::WorkspaceInfo;

fn main() -> ExitCode {
    match run() {
        Ok(code) => code,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::from(1)
        }
    }
}

fn run() -> Result<ExitCode> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Build {
            crate_name,
            tspec,
            release,
            strip,
            fail_fast,
        } => match crate_name {
            None => {
                // Build all crates
                let workspace = WorkspaceInfo::discover()?;
                let results = build_all(&workspace, tspec.as_deref(), release, strip, fail_fast);
                return Ok(print_summary(&results));
            }
            Some(name) => {
                let result = build_crate(&name, tspec.as_deref(), release)?;
                if strip {
                    strip_binary(&result.binary_path)?;
                }
            }
        },
        Commands::Run {
            crate_name,
            tspec,
            release,
            strip,
        } => match crate_name {
            None => {
                // Run all apps
                let workspace = WorkspaceInfo::discover()?;
                let results = run_all(&workspace, tspec.as_deref(), release, strip);
                return Ok(print_summary(&results));
            }
            Some(name) => {
                // Build, optionally strip, then run
                let result = build_crate(&name, tspec.as_deref(), release)?;
                if strip {
                    strip_binary(&result.binary_path)?;
                }
                let exit_code = run_binary(&result.binary_path)?;
                std::process::exit(exit_code);
            }
        },
        Commands::Test {
            crate_name,
            tspec,
            release,
            fail_fast,
        } => match crate_name {
            None => {
                // Test all crates
                let workspace = WorkspaceInfo::discover()?;
                let results = test_all(&workspace, tspec.as_deref(), release, fail_fast);
                return Ok(print_test_summary(&results));
            }
            Some(name) => {
                test_crate(&name, tspec.as_deref(), release)?;
            }
        },
        Commands::Compare {
            crate_name,
            spec_a,
            spec_b,
            release,
            strip,
        } => {
            compare_specs(&crate_name, &spec_a, &spec_b, release, strip)?;
        }
        Commands::Compat { crate_name, spec } => {
            match spec {
                Some(s) => println!("compat add: crate={crate_name} spec={s}"),
                None => println!("compat show: crate={crate_name}"),
            }
            // TODO: implement
        }
        Commands::Incompat { crate_name, spec } => {
            println!("incompat add: crate={crate_name} spec={spec}");
            // TODO: implement
        }
        Commands::Spec { command } => {
            match command {
                SpecCommands::List => {
                    println!("spec list");
                    // TODO: implement
                }
                SpecCommands::Show { name, crate_name } => {
                    println!("spec show: name={name} crate={crate_name:?}");
                    // TODO: implement
                }
                SpecCommands::Hash { name, crate_name } => {
                    println!("spec hash: name={name} crate={crate_name:?}");
                    // TODO: implement
                }
            }
        }
    }

    Ok(ExitCode::SUCCESS)
}

